DROP TABLE IF EXISTS `pengaturan_pendonor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `pengaturan_pendonor` (
  `id_pendonor` int(11) NOT NULL,
  `notif_push` tinyint(1) NOT NULL DEFAULT 1,
  `notif_email` tinyint(1) NOT NULL DEFAULT 0,
  `notif_sms` tinyint(1) NOT NULL DEFAULT 1,
  `bahasa` varchar(5) NOT NULL DEFAULT 'id',
  `tema` varchar(10) NOT NULL DEFAULT 'light',
  PRIMARY KEY (`id_pendonor`),
  CONSTRAINT `pengaturan_pendonor_id_pendonor_fkey` FOREIGN KEY (`id_pendonor`) REFERENCES `pendonor` (`id_pendonor`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
