--
-- Table structure for table `riwayat_donor`
--

DROP TABLE IF EXISTS `riwayat_donor`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `riwayat_donor` (
  `id_riwayat` int(11) NOT NULL AUTO_INCREMENT,
  `id_admin` int(11) NOT NULL,
  `id_pendonor` int(11) NOT NULL,
  `tanggal_donor` date NOT NULL,
  `status_donor` enum('berhasil','gagal','ditunda') NOT NULL,
  `lokasi_donor` varchar(150) NOT NULL,
  `keterangan` text DEFAULT NULL,
  `darah_terkumpul` int(11) DEFAULT NULL,
  `hemoglobin` decimal(4,1) DEFAULT NULL,
  `status_skrining` enum('negatif','positif','pending') DEFAULT NULL,
  `tekanan_darah_diastole` int(11) DEFAULT NULL,
  `tekanan_darah_sistole` int(11) DEFAULT NULL,
  PRIMARY KEY (`id_riwayat`),
  KEY `fk_riwayat_admin` (`id_admin`),
  KEY `fk_riwayat_pendonor` (`id_pendonor`),
  CONSTRAINT `fk_riwayat_admin` FOREIGN KEY (`id_admin`) REFERENCES `admin` (`id_admin`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `fk_riwayat_pendonor` FOREIGN KEY (`id_pendonor`) REFERENCES `pendonor` (`id_pendonor`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=1418 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

